import{_ as a,o,c as t,a2 as n}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_cover.png",r="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_01_evolution.png",c="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_02_registration.png",s="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_03_component_lifecycle.png",l="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_04_executor_stack.png",p="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_05_message_paths.png",d="/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_06_container_tradeoffs.png",q=JSON.parse('{"title":"一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信","description":"ROS 2 Composition 的核心，是把“节点写成什么样”和“节点运行在哪个进程”解耦。","frontmatter":{"title":"一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信","description":"ROS 2 Composition 的核心，是把“节点写成什么样”和“节点运行在哪个进程”解耦。","date":"2026-07-20","topic":"Nav2 工程实践","section":"六 · ROS 2 接口与工程实践","readingTime":15,"source":"2026-07-20/ros2_composition_rclcpp_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-20/ros2_composition_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/ros2-composition-rclcpp-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信"}],["meta",{"property":"og:description","content":"ROS 2 Composition 的核心，是把“节点写成什么样”和“节点运行在哪个进程”解耦。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/ros2-composition-rclcpp-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-20"}],["meta",{"name":"twitter:title","content":"一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信"}],["meta",{"name":"twitter:description","content":"ROS 2 Composition 的核心，是把“节点写成什么样”和“节点运行在哪个进程”解耦。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-20/ros2_composition_cover.png"}]],"prev":{"text":"一条 Path，如何被四个残差“拉顺又避障”？拆解 Nav2 Constrained Smoother 的 Ceres 公式","link":"/nav2/nav2-constrained-smoother-source-walkthrough"},"next":{"text":"三个回调为什么到了规划器只剩两个？从 Nav2 源码拆透 ROS 2 Action","link":"/nav2/ros2-action-callbacks-source-design"}},"headers":[],"relativePath":"nav2/ros2-composition-rclcpp-full-dataflow.md","filePath":"nav2/ros2-composition-rclcpp-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/ros2-composition-rclcpp-full-dataflow.md"};function u(m,e,_,b,g,x){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="一个进程装下整套-ros-2-从-componentmanager-一路拆到-rcl、rmw-与进程内通信" tabindex="-1">一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信 <a class="header-anchor" href="#一个进程装下整套-ros-2-从-componentmanager-一路拆到-rcl、rmw-与进程内通信" aria-label="Permalink to &quot;一个进程装下整套 ROS 2？从 ComponentManager 一路拆到 rcl、rmw 与进程内通信&quot;">​</a></h1><blockquote><p>本文以本机 ROS 2 Humble 16.0.12 为实现基线，整理 Composition 的机制演变、组件注册、动态加载、Executor 调度、进程内与跨进程消息路径，以及与 <code>rcl</code>、<code>rmw</code> 的底层边界。文中的“全部 rclcpp 调用”特指 Composition 从注册、加载到消息回调这一完整相关链路，不泛指 rclcpp 的全部 API。</p></blockquote><p><img src="'+i+'" alt="封面：ROS 2 Composition 组合机制"></p><h2 id="一、先给结论-composition-改的是进程拓扑-不是节点语义" tabindex="-1">一、先给结论：Composition 改的是进程拓扑，不是节点语义 <a class="header-anchor" href="#一、先给结论-composition-改的是进程拓扑-不是节点语义" aria-label="Permalink to &quot;一、先给结论：Composition 改的是进程拓扑，不是节点语义&quot;">​</a></h2><p>ROS 2 Composition 的核心，是把“节点写成什么样”和“节点运行在哪个进程”解耦。</p><p>同一个 <code>rclcpp::Node</code> 派生类可以：</p><ul><li>由自己生成的 <code>main()</code> 单独运行。</li><li>在编译期链接进自定义进程。</li><li>以共享库形式，在运行时装入通用组件容器。</li><li>由 launch 文件声明多个 <code>ComposableNode</code>，统一加载进一个容器。</li></ul><p>节点的 Topic、Service、Action、Parameter、Lifecycle 和 TF 语义都不因为 Composition 而改变。改变的是这些实体由哪个进程持有、由哪个 Executor 调度，以及消息是否具备走进程内路径的条件。</p><p>这带来三个必须分开的概念：</p><ul><li>Composition：多个节点位于同一进程。</li><li>Executor：决定这些节点的回调在哪些线程、按什么互斥规则执行。</li><li>Intra-process communication：在满足条件时绕过序列化与 DDS 数据路径。</li></ul><p>三者有关联，但不是同一件事。</p><p><img src="'+r+`" alt="图 1：从 ROS 1 Nodelet 到 ROS 2 统一组件模型"></p><h2 id="二、机制是怎样演变来的" tabindex="-1">二、机制是怎样演变来的 <a class="header-anchor" href="#二、机制是怎样演变来的" aria-label="Permalink to &quot;二、机制是怎样演变来的&quot;">​</a></h2><h3 id="_2-1-ros-1-node-与-nodelet-是两套编程模型" tabindex="-1">2.1 ROS 1：Node 与 Nodelet 是两套编程模型 <a class="header-anchor" href="#_2-1-ros-1-node-与-nodelet-是两套编程模型" aria-label="Permalink to &quot;2.1 ROS 1：Node 与 Nodelet 是两套编程模型&quot;">​</a></h3><p>ROS 1 普通节点编译成独立可执行文件，Nodelet 则编译成共享库，再装入 Nodelet Manager。Nodelet 能降低同机大数据消息的复制成本，但开发者需要面对不同基类、不同初始化入口和不同部署方式。</p><p>这意味着“要不要共进程”在很大程度上会反向影响代码结构。</p><h3 id="_2-2-ros-2-统一为-node-api-把进程布局推迟到部署阶段" tabindex="-1">2.2 ROS 2：统一为 Node API，把进程布局推迟到部署阶段 <a class="header-anchor" href="#_2-2-ros-2-统一为-node-api-把进程布局推迟到部署阶段" aria-label="Permalink to &quot;2.2 ROS 2：统一为 Node API，把进程布局推迟到部署阶段&quot;">​</a></h3><p>ROS 2 推荐把可复用节点写成 Component。Component 通常仍是 <code>rclcpp::Node</code> 的子类，只是构造函数接收 <code>rclcpp::NodeOptions</code>，并导出一个节点工厂入口。</p><p>于是，业务代码不需要为了独立进程或组合进程维护两套实现。部署者可以根据故障隔离、调试、内存、延迟和调度需求选择进程布局。</p><h3 id="_2-3-运行时组件管理-service-驱动动态装载" tabindex="-1">2.3 运行时组件管理：Service 驱动动态装载 <a class="header-anchor" href="#_2-3-运行时组件管理-service-驱动动态装载" aria-label="Permalink to &quot;2.3 运行时组件管理：Service 驱动动态装载&quot;">​</a></h3><p><code>rclcpp_components::ComponentManager</code> 提供 LoadNode、UnloadNode 和 ListNodes 三个 Service。<code>ros2 component</code>、launch 或其他客户端都可以在容器运行后请求装载组件。</p><h3 id="_2-4-进程内通信的第一次实现-环形缓冲区加元消息" tabindex="-1">2.4 进程内通信的第一次实现：环形缓冲区加元消息 <a class="header-anchor" href="#_2-4-进程内通信的第一次实现-环形缓冲区加元消息" aria-label="Permalink to &quot;2.4 进程内通信的第一次实现：环形缓冲区加元消息&quot;">​</a></h3><p>早期 ROS 2 进程内通信以 Publisher 环形缓冲区保存原消息，再通过中间件发送只包含 Publisher ID 和缓冲位置的元消息。订阅端收到元消息后，再回到 <code>IntraProcessManager</code> 取原数据。</p><p>这种方式仍依赖中间件通知，并且在共享指针、内存占用和性能方面存在限制。</p><h3 id="_2-5-dashing-之后-订阅端缓冲区加-guardcondition" tabindex="-1">2.5 Dashing 之后：订阅端缓冲区加 GuardCondition <a class="header-anchor" href="#_2-5-dashing-之后-订阅端缓冲区加-guardcondition" aria-label="Permalink to &quot;2.5 Dashing 之后：订阅端缓冲区加 GuardCondition&quot;">​</a></h3><p>新的实现让每个进程内订阅拥有自己的缓冲区。Publisher 把消息直接交给 <code>IntraProcessManager</code>，管理器按订阅回调的所有权需求选择共享、复制或转移 <code>unique_ptr</code>，然后触发订阅对应的 GuardCondition。Executor 把它作为 Waitable 处理，不再依赖元消息唤醒。</p><p>Humble 当前使用的就是这条架构。</p><h3 id="_2-6-容器调度继续细分" tabindex="-1">2.6 容器调度继续细分 <a class="header-anchor" href="#_2-6-容器调度继续细分" aria-label="Permalink to &quot;2.6 容器调度继续细分&quot;">​</a></h3><p>当前 Humble 提供三种通用容器：</p><ul><li><code>component_container</code>：所有组件共享一个 <code>SingleThreadedExecutor</code>。</li><li><code>component_container_mt</code>：所有组件共享一个 <code>MultiThreadedExecutor</code>。</li><li><code>component_container_isolated</code>：每个组件拥有独立 Executor 和线程。</li></ul><p>这一步让“同进程低开销”和“调度隔离”不再只能二选一，但同进程组件仍共享地址空间，内存破坏和进程崩溃无法隔离。</p><h2 id="三、一个类怎样变成可发现的-component" tabindex="-1">三、一个类怎样变成可发现的 Component <a class="header-anchor" href="#三、一个类怎样变成可发现的-component" aria-label="Permalink to &quot;三、一个类怎样变成可发现的 Component&quot;">​</a></h2><p>Component 类需要满足两个关键约定：</p><ul><li>构造函数接收单个 <code>rclcpp::NodeOptions</code>。</li><li>能返回 <code>NodeBaseInterface</code>。继承 <code>rclcpp::Node</code> 时天然满足这一点。</li></ul><p>源文件末尾调用：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">RCLCPP_COMPONENTS_REGISTER_NODE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my_pkg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::MyNode)</span></span></code></pre></div><p>这个宏不会创建 ROS 节点。它展开为 <code>CLASS_LOADER_REGISTER_CLASS</code>，注册的实际类型是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rclcpp_components::NodeFactoryTemplate&lt;my_pkg::MyNode&gt;</span></span>
<span class="line"><span>  implements rclcpp_components::NodeFactory</span></span></code></pre></div><p>工厂的 <code>create_node_instance()</code> 才会在运行时执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>std::make_shared&lt;MyNode&gt;(options)</span></span>
<span class="line"><span>  -&gt; NodeInstanceWrapper</span></span>
<span class="line"><span>       ├─ std::shared_ptr&lt;void&gt; 保存真实对象</span></span>
<span class="line"><span>       └─ get_node_base_interface() 提供给 Executor</span></span></code></pre></div><p>CMake 侧的 <code>rclcpp_components_register_nodes()</code> 做另一半工作：它要求目标是共享库，并向 ament resource index 写入“插件类名；共享库路径”。</p><p>所以组件发现依赖两份信息同时存在：</p><ul><li>共享库内部的 class_loader 工厂注册。</li><li>安装空间 ament index 中的类名与库路径映射。</li></ul><p>少任何一个，<code>ros2 component types</code> 或 ComponentManager 都无法正确实例化组件。</p><p><img src="`+c+`" alt="图 2：编译注册、ament 索引与运行时发现"></p><h2 id="四、容器进程启动时-rclcpp-做了什么" tabindex="-1">四、容器进程启动时，rclcpp 做了什么 <a class="header-anchor" href="#四、容器进程启动时-rclcpp-做了什么" aria-label="Permalink to &quot;四、容器进程启动时，rclcpp 做了什么&quot;">​</a></h2><p>以单线程容器为例，<code>main()</code> 非常短：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rclcpp::init(argc, argv)</span></span>
<span class="line"><span>  -&gt; 创建 SingleThreadedExecutor</span></span>
<span class="line"><span>  -&gt; 创建 ComponentManager(executor)</span></span>
<span class="line"><span>  -&gt; executor.add_node(component_manager)</span></span>
<span class="line"><span>  -&gt; executor.spin()</span></span></code></pre></div><p>ComponentManager 本身也是一个 <code>rclcpp::Node</code>。构造时创建三个管理 Service：</p><ul><li><code>~/_container/load_node</code></li><li><code>~/_container/unload_node</code></li><li><code>~/_container/list_nodes</code></li></ul><p>假设容器节点名为 <code>/nav2_container</code>，第一个私有名称会展开为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nav2_container/_container/load_node</span></span></code></pre></div><p>Load 和 Unload Service 的 QoS 深度在当前实现中被设为 200。ComponentManager 自己默认关闭参数 Service 和参数事件发布器，但会声明只读参数 <code>thread_num</code>，供多线程容器决定线程数量。</p><p>容器启动后还没有业务组件。此时 Executor 只调度 ComponentManager 自己的三个 Service 和节点基础实体。</p><h2 id="五、loadnode-请求携带哪些输入" tabindex="-1">五、LoadNode 请求携带哪些输入 <a class="header-anchor" href="#五、loadnode-请求携带哪些输入" aria-label="Permalink to &quot;五、LoadNode 请求携带哪些输入&quot;">​</a></h2><h3 id="_5-1-请求字段" tabindex="-1">5.1 请求字段 <a class="header-anchor" href="#_5-1-请求字段" aria-label="Permalink to &quot;5.1 请求字段&quot;">​</a></h3><p><code>composition_interfaces/srv/LoadNode</code> 请求包含：</p><ul><li><code>package_name</code>：组件所属 ROS 包。</li><li><code>plugin_name</code>：注册到索引中的插件类名。</li><li><code>node_name</code>：实例节点名，可为空。</li><li><code>node_namespace</code>：实例命名空间，可为空。</li><li><code>log_level</code>：请求字段；Humble 当前 <code>create_node_options()</code> 没有消费它。</li><li><code>remap_rules</code>：组件专属 remapping。</li><li><code>parameters</code>：已解析为 <code>rcl_interfaces/msg/Parameter</code> 的参数覆盖。</li><li><code>extra_arguments</code>：容器专属键值参数。</li></ul><h3 id="_5-2-响应字段" tabindex="-1">5.2 响应字段 <a class="header-anchor" href="#_5-2-响应字段" aria-label="Permalink to &quot;5.2 响应字段&quot;">​</a></h3><p>响应包含：</p><ul><li><code>success</code>。</li><li><code>error_message</code>。</li><li><code>full_node_name</code>。</li><li>容器内唯一的 <code>unique_id</code>。</li></ul><h3 id="_5-3-extra-arguments" tabindex="-1">5.3 Extra Arguments <a class="header-anchor" href="#_5-3-extra-arguments" aria-label="Permalink to &quot;5.3 Extra Arguments&quot;">​</a></h3><p>Humble 当前识别两个关键 extra argument：</p><ul><li><code>use_intra_process_comms</code>：写入 <code>NodeOptions::use_intra_process_comms()</code>。</li><li><code>forward_global_arguments</code>：决定组件是否接收容器进程的全局 ROS 参数。默认关闭，以防某个组件被不属于它的全局 remap 或参数影响。</li></ul><p>launch 中的 <code>LoadComposableNodes</code> 会先解析名字、命名空间、参数文件、remapping 和 extra arguments，构造 LoadNode 请求，然后按列表顺序逐个调用容器 Service。参数文件路径本身不会传给 ComponentManager；launch 已经把它转换成 Parameter 数组。</p><h2 id="六、动态装载全链路-从-service-到-dlopen" tabindex="-1">六、动态装载全链路：从 Service 到 <code>dlopen</code> <a class="header-anchor" href="#六、动态装载全链路-从-service-到-dlopen" aria-label="Permalink to &quot;六、动态装载全链路：从 Service 到 \`dlopen\`&quot;">​</a></h2><p>外部客户端发送 LoadNode 请求后，容器侧走的是普通 ROS 2 Service 数据路径：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rmw_wait</span></span>
<span class="line"><span>  -&gt; rcl_wait</span></span>
<span class="line"><span>  -&gt; Executor 发现 Service ready</span></span>
<span class="line"><span>  -&gt; execute_service()</span></span>
<span class="line"><span>  -&gt; ServiceBase::take_type_erased_request()</span></span>
<span class="line"><span>  -&gt; rcl_take_request()</span></span>
<span class="line"><span>  -&gt; rmw_take_request()</span></span>
<span class="line"><span>  -&gt; ComponentManager::on_load_node()</span></span></code></pre></div><p><code>on_load_node()</code> 内部按下面的顺序执行。</p><h3 id="_6-1-读取-ament-index" tabindex="-1">6.1 读取 Ament Index <a class="header-anchor" href="#_6-1-读取-ament-index" aria-label="Permalink to &quot;6.1 读取 Ament Index&quot;">​</a></h3><p><code>ament_index_cpp::get_resource()</code> 读取包在 <code>rclcpp_components</code> 资源索引中的条目。</p><h3 id="_6-2-解析插件与共享库" tabindex="-1">6.2 解析插件与共享库 <a class="header-anchor" href="#_6-2-解析插件与共享库" aria-label="Permalink to &quot;6.2 解析插件与共享库&quot;">​</a></h3><p>找到与 <code>plugin_name</code> 相同的类名和共享库绝对路径。</p><h3 id="_6-3-打开动态库" tabindex="-1">6.3 打开动态库 <a class="header-anchor" href="#_6-3-打开动态库" aria-label="Permalink to &quot;6.3 打开动态库&quot;">​</a></h3><p>为该共享库创建或复用 <code>class_loader::ClassLoader</code>，底层打开动态库。</p><h3 id="_6-4-创建-nodefactory" tabindex="-1">6.4 创建 NodeFactory <a class="header-anchor" href="#_6-4-创建-nodefactory" aria-label="Permalink to &quot;6.4 创建 NodeFactory&quot;">​</a></h3><p>寻找 <code>NodeFactoryTemplate&lt;组件类&gt;</code>，创建 NodeFactory。</p><h3 id="_6-5-构造-nodeoptions" tabindex="-1">6.5 构造 NodeOptions <a class="header-anchor" href="#_6-5-构造-nodeoptions" aria-label="Permalink to &quot;6.5 构造 NodeOptions&quot;">​</a></h3><p>把参数、remap、名字、命名空间和 extra arguments 转成 <code>NodeOptions</code>。</p><h3 id="_6-6-分配唯一-id" tabindex="-1">6.6 分配唯一 ID <a class="header-anchor" href="#_6-6-分配唯一-id" aria-label="Permalink to &quot;6.6 分配唯一 ID&quot;">​</a></h3><p>分配容器内唯一 ID。</p><h3 id="_6-7-构造组件实例" tabindex="-1">6.7 构造组件实例 <a class="header-anchor" href="#_6-7-构造组件实例" aria-label="Permalink to &quot;6.7 构造组件实例&quot;">​</a></h3><p>工厂执行 <code>std::make_shared&lt;NodeT&gt;(options)</code>，组件构造函数在这里运行。</p><h3 id="_6-8-保存实例包装器" tabindex="-1">6.8 保存实例包装器 <a class="header-anchor" href="#_6-8-保存实例包装器" aria-label="Permalink to &quot;6.8 保存实例包装器&quot;">​</a></h3><p><code>NodeInstanceWrapper</code> 同时保存真实对象和 NodeBaseInterface 访问器。</p><h3 id="_6-9-加入-executor" tabindex="-1">6.9 加入 Executor <a class="header-anchor" href="#_6-9-加入-executor" aria-label="Permalink to &quot;6.9 加入 Executor&quot;">​</a></h3><p><code>Executor::add_node()</code> 把组件的自动 callback groups 纳入调度集合。</p><h3 id="_6-10-返回装载结果" tabindex="-1">6.10 返回装载结果 <a class="header-anchor" href="#_6-10-返回装载结果" aria-label="Permalink to &quot;6.10 返回装载结果&quot;">​</a></h3><p>返回完整节点名与唯一 ID，再由 Service 通过 <code>rcl_send_response()</code> 和 <code>rmw_send_response()</code> 发回客户端。</p><p><img src="`+s+'" alt="图 3：Load、List、Unload 状态与数据流"></p><h3 id="_6-11-装载失败出口" tabindex="-1">6.11 装载失败出口 <a class="header-anchor" href="#_6-11-装载失败出口" aria-label="Permalink to &quot;6.11 装载失败出口&quot;">​</a></h3><p>装载失败的主要出口包括：</p><ul><li>ament index 找不到包资源。</li><li>资源条目格式错误。</li><li>共享库打开失败。</li><li>找不到请求的插件类。</li><li>extra argument 类型错误。</li><li>组件构造函数抛异常。</li></ul><p>这些错误写入 <code>success=false</code> 和 <code>error_message</code>，不会把半初始化组件加入 Executor。</p><h2 id="七、unload-与-list-被销毁的是实例-不一定立即卸载动态库" tabindex="-1">七、Unload 与 List：被销毁的是实例，不一定立即卸载动态库 <a class="header-anchor" href="#七、unload-与-list-被销毁的是实例-不一定立即卸载动态库" aria-label="Permalink to &quot;七、Unload 与 List：被销毁的是实例，不一定立即卸载动态库&quot;">​</a></h2><h3 id="_7-1-listnodes" tabindex="-1">7.1 ListNodes <a class="header-anchor" href="#_7-1-listnodes" aria-label="Permalink to &quot;7.1 ListNodes&quot;">​</a></h3><p>ListNodes 遍历 <code>node_wrappers_</code>，返回平行数组 <code>full_node_names</code> 和 <code>unique_ids</code>。</p><h3 id="_7-2-unloadnode" tabindex="-1">7.2 UnloadNode <a class="header-anchor" href="#_7-2-unloadnode" aria-label="Permalink to &quot;7.2 UnloadNode&quot;">​</a></h3><p>UnloadNode 只接收 <code>unique_id</code>，并按以下步骤执行。</p><h4 id="_7-2-1-查找实例" tabindex="-1">7.2.1 查找实例 <a class="header-anchor" href="#_7-2-1-查找实例" aria-label="Permalink to &quot;7.2.1 查找实例&quot;">​</a></h4><p>在 <code>node_wrappers_</code> 查找实例。</p><h4 id="_7-2-2-移除-callback-groups" tabindex="-1">7.2.2 移除 Callback Groups <a class="header-anchor" href="#_7-2-2-移除-callback-groups" aria-label="Permalink to &quot;7.2.2 移除 Callback Groups&quot;">​</a></h4><p><code>Executor::remove_node()</code> 移除其 callback groups。</p><h4 id="_7-2-3-擦除实例包装器" tabindex="-1">7.2.3 擦除实例包装器 <a class="header-anchor" href="#_7-2-3-擦除实例包装器" aria-label="Permalink to &quot;7.2.3 擦除实例包装器&quot;">​</a></h4><p>从 map 擦除 NodeInstanceWrapper。</p><h4 id="_7-2-4-析构节点资源" tabindex="-1">7.2.4 析构节点资源 <a class="header-anchor" href="#_7-2-4-析构节点资源" aria-label="Permalink to &quot;7.2.4 析构节点资源&quot;">​</a></h4><p>共享指针引用归零时，节点及其 Publisher、Subscription、Timer、Service 等实体析构。</p><p>当前 ComponentManager 会缓存每个共享库对应的 ClassLoader。卸载一个组件实例时不会同步擦除这个 loader，因此“节点对象已销毁”不等于“共享库立刻 dlclose”。这是避免频繁开关动态库的一种实现结果，也解释了为什么卸载后静态变量和库级资源不一定马上消失。</p><h2 id="八、executor-怎样调度同一进程中的所有组件" tabindex="-1">八、Executor 怎样调度同一进程中的所有组件 <a class="header-anchor" href="#八、executor-怎样调度同一进程中的所有组件" aria-label="Permalink to &quot;八、Executor 怎样调度同一进程中的所有组件&quot;">​</a></h2><p>组件加入 Executor 后，不是获得自己的 <code>spin()</code>。Component 自己没有主线程控制权，所有回调由容器 Executor 统一调度。</p><p>单线程 Executor 的核心循环可以概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>while context ok:</span></span>\n<span class="line"><span>  get_next_executable()</span></span>\n<span class="line"><span>  execute_any_executable()</span></span></code></pre></div><h3 id="_8-1-wait-for-work-等待流程" tabindex="-1">8.1 <code>wait_for_work()</code> 等待流程 <a class="header-anchor" href="#_8-1-wait-for-work-等待流程" aria-label="Permalink to &quot;8.1 `wait_for_work()` 等待流程&quot;">​</a></h3><p>当没有立即可执行的任务时，<code>wait_for_work()</code> 按以下步骤执行。</p><h4 id="_8-1-1-收集-callback-groups" tabindex="-1">8.1.1 收集 Callback Groups <a class="header-anchor" href="#_8-1-1-收集-callback-groups" aria-label="Permalink to &quot;8.1.1 收集 Callback Groups&quot;">​</a></h4><p>收集各节点自动加入的 CallbackGroup。</p><h4 id="_8-1-2-收集可执行实体" tabindex="-1">8.1.2 收集可执行实体 <a class="header-anchor" href="#_8-1-2-收集可执行实体" aria-label="Permalink to &quot;8.1.2 收集可执行实体&quot;">​</a></h4><p>由 MemoryStrategy 收集 Subscription、Timer、Service、Client、GuardCondition 和 Waitable。</p><h4 id="_8-1-3-调整-waitset" tabindex="-1">8.1.3 调整 WaitSet <a class="header-anchor" href="#_8-1-3-调整-waitset" aria-label="Permalink to &quot;8.1.3 调整 WaitSet&quot;">​</a></h4><p>清空并调整 <code>rcl_wait_set_t</code> 容量。</p><h4 id="_8-1-4-加入实体句柄" tabindex="-1">8.1.4 加入实体句柄 <a class="header-anchor" href="#_8-1-4-加入实体句柄" aria-label="Permalink to &quot;8.1.4 加入实体句柄&quot;">​</a></h4><p>将各实体句柄加入 WaitSet。</p><h4 id="_8-1-5-调用-rcl-wait" tabindex="-1">8.1.5 调用 <code>rcl_wait()</code> <a class="header-anchor" href="#_8-1-5-调用-rcl-wait" aria-label="Permalink to &quot;8.1.5 调用 `rcl_wait()`&quot;">​</a></h4><p>调用 <code>rcl_wait()</code>。</p><h4 id="_8-1-6-进入-rmw-等待" tabindex="-1">8.1.6 进入 RMW 等待 <a class="header-anchor" href="#_8-1-6-进入-rmw-等待" aria-label="Permalink to &quot;8.1.6 进入 RMW 等待&quot;">​</a></h4><p><code>rcl_wait()</code> 将等待请求交给 <code>rmw_wait()</code>，再由具体 RMW／DDS 实现阻塞等待数据或事件。</p><h4 id="_8-1-7-选择可执行任务" tabindex="-1">8.1.7 选择可执行任务 <a class="header-anchor" href="#_8-1-7-选择可执行任务" aria-label="Permalink to &quot;8.1.7 选择可执行任务&quot;">​</a></h4><p>醒来后删除未就绪的空句柄，从 ready 集合选择一个 AnyExecutable。</p><p>Humble 当前普通 Executor 的选择顺序是 Timer、Subscription、Service、Client、Waitable。选中互斥 CallbackGroup 后，会先把 <code>can_be_taken_from</code> 置为 false，执行结束再恢复，防止多线程 Executor 同时运行同组回调。</p><p><img src="'+l+`" alt="图 4：Executor 下沉到 rcl、rmw 的调用栈"></p><h3 id="_8-2-execute-any-executable-回调分发" tabindex="-1">8.2 <code>execute_any_executable()</code> 回调分发 <a class="header-anchor" href="#_8-2-execute-any-executable-回调分发" aria-label="Permalink to &quot;8.2 \`execute_any_executable()\` 回调分发&quot;">​</a></h3><p><code>execute_any_executable()</code> 再按实体类型分发：</p><ul><li>Timer：<code>TimerBase::execute_callback()</code>。</li><li>Subscription：<code>execute_subscription()</code>。</li><li>Service：<code>take_type_erased_request()</code> 后执行服务回调。</li><li>Client：<code>take_type_erased_response()</code> 后完成 Future 和回调。</li><li>Waitable：<code>take_data()</code> 后执行 <code>execute()</code>，进程内订阅就是这一类。</li></ul><p>这解释了一个常见误区：组件共进程后，如果使用单线程容器，而某个回调长时间阻塞，其他组件的 Timer、Service 和 Subscription 一样会被拖住。</p><h2 id="九、跨进程消息-仍然经过-rcl-与-rmw" tabindex="-1">九、跨进程消息：仍然经过 rcl 与 rmw <a class="header-anchor" href="#九、跨进程消息-仍然经过-rcl-与-rmw" aria-label="Permalink to &quot;九、跨进程消息：仍然经过 rcl 与 rmw&quot;">​</a></h2><p>当未启用进程内通信，或订阅者位于其他进程时，Publisher 的路径是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rclcpp::Publisher&lt;MessageT&gt;::publish()</span></span>
<span class="line"><span>  -&gt; do_inter_process_publish()</span></span>
<span class="line"><span>  -&gt; rcl_publish()</span></span>
<span class="line"><span>  -&gt; rmw_publish()</span></span>
<span class="line"><span>  -&gt; 具体 DDS／中间件发送</span></span></code></pre></div><p>订阅端由 WaitSet 唤醒后：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Executor::execute_subscription()</span></span>
<span class="line"><span>  -&gt; SubscriptionBase::take_type_erased()</span></span>
<span class="line"><span>  -&gt; rcl_take()</span></span>
<span class="line"><span>  -&gt; rmw_take()</span></span>
<span class="line"><span>  -&gt; Subscription::handle_message()</span></span>
<span class="line"><span>  -&gt; AnySubscriptionCallback::dispatch()</span></span>
<span class="line"><span>  -&gt; 用户回调</span></span></code></pre></div><p>因此，同一容器里两个组件即使物理上共进程，只要 <code>use_intra_process_comms</code> 没开启，它们仍走普通 RMW 通信路径。</p><h2 id="十、进程内消息-不序列化-但也不是永远零复制" tabindex="-1">十、进程内消息：不序列化，但也不是永远零复制 <a class="header-anchor" href="#十、进程内消息-不序列化-但也不是永远零复制" aria-label="Permalink to &quot;十、进程内消息：不序列化，但也不是永远零复制&quot;">​</a></h2><p><code>NodeOptions::use_intra_process_comms</code> 在 Humble 默认是 false。通过 Component 的 extra argument 打开后，Publisher 和 Subscription 会向同一个 <code>rclcpp::Context</code> 持有的 <code>IntraProcessManager</code> 注册。</p><h3 id="_10-1-通信匹配条件" tabindex="-1">10.1 通信匹配条件 <a class="header-anchor" href="#_10-1-通信匹配条件" aria-label="Permalink to &quot;10.1 通信匹配条件&quot;">​</a></h3><p>注册时，管理器按两个条件匹配通信对：</p><ul><li>完全相同的最终 Topic 名称。</li><li>QoS 兼容。</li></ul><h3 id="_10-2-unique-ptr-发布链路" tabindex="-1">10.2 <code>unique_ptr</code> 发布链路 <a class="header-anchor" href="#_10-2-unique-ptr-发布链路" aria-label="Permalink to &quot;10.2 \`unique_ptr\` 发布链路&quot;">​</a></h3><p>Publisher 发布 <code>unique_ptr</code> 时，调用链变为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Publisher::publish(unique_ptr)</span></span>
<span class="line"><span>  -&gt; do_intra_process_publish()</span></span>
<span class="line"><span>  -&gt; IntraProcessManager::do_intra_process_publish()</span></span>
<span class="line"><span>  -&gt; 按订阅所有权类型选择目标</span></span>
<span class="line"><span>  -&gt; 写入每个 SubscriptionIntraProcessBuffer</span></span>
<span class="line"><span>  -&gt; 触发 GuardCondition</span></span>
<span class="line"><span>  -&gt; Executor 将其作为 Waitable 取出</span></span>
<span class="line"><span>  -&gt; SubscriptionIntraProcess::take_data()</span></span>
<span class="line"><span>  -&gt; dispatch_intra_process()</span></span>
<span class="line"><span>  -&gt; 用户回调</span></span></code></pre></div><p><img src="`+p+'" alt="图 5：跨进程与进程内消息双路径"></p><h3 id="_10-3-消息所有权与复制" tabindex="-1">10.3 消息所有权与复制 <a class="header-anchor" href="#_10-3-消息所有权与复制" aria-label="Permalink to &quot;10.3 消息所有权与复制&quot;">​</a></h3><p>复制次数由订阅回调类型决定：</p><ul><li>全部订阅只要求共享所有权时，<code>unique_ptr</code> 可提升为共享指针，多个订阅共享消息。</li><li>有订阅要求独占所有权时，除最后一个接收者可以获得原 <code>unique_ptr</code> 外，其他独占订阅仍需要复制。</li><li>共享订阅与多个独占订阅混合时，需要为不同所有权分支创建副本。</li><li>使用 <code>publish(const MessageT&amp;)</code> 时，为进入进程内所有权链，Publisher 会先在堆上复制成 <code>unique_ptr</code>。</li><li>Humble 的进程内路径不支持 serialized message；LoanedMessage 与进程内通信同时启用时也不支持。</li></ul><p>如果同一 Publisher 同时存在进程内和外部订阅，rclcpp 会先走进程内分发，再调用 <code>rcl_publish()</code> 满足外部订阅。订阅端若从 RMW 路径收到来自本进程已匹配 Publisher 的重复副本，会根据 Publisher GID 丢弃，避免同一回调收到两次。</p><h3 id="_10-4-零复制成立条件" tabindex="-1">10.4 零复制成立条件 <a class="header-anchor" href="#_10-4-零复制成立条件" aria-label="Permalink to &quot;10.4 零复制成立条件&quot;">​</a></h3><p>所以“同进程”只是前提，“零复制”仍取决于：</p><ul><li>是否显式启用 IPC。</li><li>Publisher 与 Subscription 是否共享同一个 Context。</li><li>Topic 和 QoS 是否匹配。</li><li>发布参数是否转移所有权。</li><li>订阅回调要求 shared ownership 还是 unique ownership。</li><li>是否还存在外部订阅者。</li></ul><h2 id="十一、三个容器该怎样选" tabindex="-1">十一、三个容器该怎样选 <a class="header-anchor" href="#十一、三个容器该怎样选" aria-label="Permalink to &quot;十一、三个容器该怎样选&quot;">​</a></h2><h3 id="_11-1-component-container" tabindex="-1">11.1 <code>component_container</code> <a class="header-anchor" href="#_11-1-component-container" aria-label="Permalink to &quot;11.1 `component_container`&quot;">​</a></h3><p>所有组件共享一个线程，行为最容易推理，适合回调短小、无阻塞、并发要求低的系统。任何长回调都会阻塞整个容器。</p><h3 id="_11-2-component-container-mt" tabindex="-1">11.2 <code>component_container_mt</code> <a class="header-anchor" href="#_11-2-component-container-mt" aria-label="Permalink to &quot;11.2 `component_container_mt`&quot;">​</a></h3><p>所有组件共享线程池。是否真能并发由 CallbackGroup 决定；如果所有实体都留在同一个默认 MutuallyExclusive 组，即使有多个线程，同一节点内部也不会自动并行。</p><h3 id="_11-3-component-container-isolated" tabindex="-1">11.3 <code>component_container_isolated</code> <a class="header-anchor" href="#_11-3-component-container-isolated" aria-label="Permalink to &quot;11.3 `component_container_isolated`&quot;">​</a></h3><p>每个组件创建独立 Executor 和线程，卸载时取消对应 Executor 并 join 线程。它增强调度隔离，却仍共享进程地址空间和全局 Context。</p><p><img src="'+d+'" alt="图 6：容器选择、隔离边界与输入输出"></p><h3 id="_11-4-容器选择顺序" tabindex="-1">11.4 容器选择顺序 <a class="header-anchor" href="#_11-4-容器选择顺序" aria-label="Permalink to &quot;11.4 容器选择顺序&quot;">​</a></h3><p>工程上可以按以下顺序判断。</p><h4 id="_11-4-1-判断是否需要进程隔离" tabindex="-1">11.4.1 判断是否需要进程隔离 <a class="header-anchor" href="#_11-4-1-判断是否需要进程隔离" aria-label="Permalink to &quot;11.4.1 判断是否需要进程隔离&quot;">​</a></h4><p>需要进程级故障隔离或单节点调试最优先时，选择独立进程。</p><h4 id="_11-4-2-判断单线程是否足够" tabindex="-1">11.4.2 判断单线程是否足够 <a class="header-anchor" href="#_11-4-2-判断单线程是否足够" aria-label="Permalink to &quot;11.4.2 判断单线程是否足够&quot;">​</a></h4><p>回调都很短、追求简单与低开销时，选择单线程容器。</p><h4 id="_11-4-3-判断是否需要并行" tabindex="-1">11.4.3 判断是否需要并行 <a class="header-anchor" href="#_11-4-3-判断是否需要并行" aria-label="Permalink to &quot;11.4.3 判断是否需要并行&quot;">​</a></h4><p>存在并行图像、点云或规划任务，并已设计 CallbackGroup 时，选择多线程容器。</p><h4 id="_11-4-4-判断是否需要调度隔离" tabindex="-1">11.4.4 判断是否需要调度隔离 <a class="header-anchor" href="#_11-4-4-判断是否需要调度隔离" aria-label="Permalink to &quot;11.4.4 判断是否需要调度隔离&quot;">​</a></h4><p>希望共享进程但减少组件间调度干扰时，选择隔离容器。</p><h2 id="十二、composition-与-lifecycle、action、parameter-的关系" tabindex="-1">十二、Composition 与 Lifecycle、Action、Parameter 的关系 <a class="header-anchor" href="#十二、composition-与-lifecycle、action、parameter-的关系" aria-label="Permalink to &quot;十二、Composition 与 Lifecycle、Action、Parameter 的关系&quot;">​</a></h2><h3 id="_12-1-composition-与-lifecycle" tabindex="-1">12.1 Composition 与 Lifecycle <a class="header-anchor" href="#_12-1-composition-与-lifecycle" aria-label="Permalink to &quot;12.1 Composition 与 Lifecycle&quot;">​</a></h3><p>Composition 不替代 Lifecycle。一个 <code>LifecycleNode</code> 被加载后，状态仍从 Unconfigured 开始，必须由 LifecycleManager 或客户端执行 configure、activate 等转换。</p><h3 id="_12-2-composition-与-action" tabindex="-1">12.2 Composition 与 Action <a class="header-anchor" href="#_12-2-composition-与-action" aria-label="Permalink to &quot;12.2 Composition 与 Action&quot;">​</a></h3><p>Composition 也不改变 Action 的五路 Topic／Service 语义；Action Server 和 Client 仍由 rclcpp_action 创建底层实体，再由同一个 Executor 调度。</p><h3 id="_12-3-composition-与-parameter" tabindex="-1">12.3 Composition 与 Parameter <a class="header-anchor" href="#_12-3-composition-与-parameter" aria-label="Permalink to &quot;12.3 Composition 与 Parameter&quot;">​</a></h3><p>Parameter 覆盖在构造组件时通过 NodeOptions 注入，但运行期参数 Service 是否存在，取决于组件自身 NodeOptions 和节点实现。ComponentManager 关闭的是自己的参数 Service，不是被加载组件的参数 Service。</p><h2 id="十三、最容易踩的十个坑" tabindex="-1">十三、最容易踩的十个坑 <a class="header-anchor" href="#十三、最容易踩的十个坑" aria-label="Permalink to &quot;十三、最容易踩的十个坑&quot;">​</a></h2><h3 id="_13-1-只写注册宏" tabindex="-1">13.1 只写注册宏 <a class="header-anchor" href="#_13-1-只写注册宏" aria-label="Permalink to &quot;13.1 只写注册宏&quot;">​</a></h3><p>没有调用 CMake 注册函数时，共享库能编译，但 ament index 找不到它。</p><h3 id="_13-2-只调用-cmake-注册" tabindex="-1">13.2 只调用 CMake 注册 <a class="header-anchor" href="#_13-2-只调用-cmake-注册" aria-label="Permalink to &quot;13.2 只调用 CMake 注册&quot;">​</a></h3><p>没有在某个翻译单元中导出工厂时，索引里有名字，动态库里却没有可实例化类。</p><h3 id="_13-3-在组件构造函数里阻塞" tabindex="-1">13.3 在组件构造函数里阻塞 <a class="header-anchor" href="#_13-3-在组件构造函数里阻塞" aria-label="Permalink to &quot;13.3 在组件构造函数里阻塞&quot;">​</a></h3><p>构造发生在 LoadNode Service 回调中，会阻塞后续加载和容器调度。</p><h3 id="_13-4-把-composition-当作-ipc-开关" tabindex="-1">13.4 把 Composition 当作 IPC 开关 <a class="header-anchor" href="#_13-4-把-composition-当作-ipc-开关" aria-label="Permalink to &quot;13.4 把 Composition 当作 IPC 开关&quot;">​</a></h3><p>共进程不自动启用 <code>use_intra_process_comms</code>。</p><h3 id="_13-5-把-ipc-当作绝对零复制" tabindex="-1">13.5 把 IPC 当作绝对零复制 <a class="header-anchor" href="#_13-5-把-ipc-当作绝对零复制" aria-label="Permalink to &quot;13.5 把 IPC 当作绝对零复制&quot;">​</a></h3><p>回调所有权和订阅数量仍可能产生副本。</p><h3 id="_13-6-在单线程容器执行耗时回调" tabindex="-1">13.6 在单线程容器执行耗时回调 <a class="header-anchor" href="#_13-6-在单线程容器执行耗时回调" aria-label="Permalink to &quot;13.6 在单线程容器执行耗时回调&quot;">​</a></h3><p>这会导致同容器全部节点“像一起卡死”。</p><h3 id="_13-7-多线程容器缺少-callbackgroup-设计" tabindex="-1">13.7 多线程容器缺少 CallbackGroup 设计 <a class="header-anchor" href="#_13-7-多线程容器缺少-callbackgroup-设计" aria-label="Permalink to &quot;13.7 多线程容器缺少 CallbackGroup 设计&quot;">​</a></h3><p>结果可能是并发度没有变化，或者共享状态出现竞态。</p><h3 id="_13-8-认为卸载组件会立即卸载共享库" tabindex="-1">13.8 认为卸载组件会立即卸载共享库 <a class="header-anchor" href="#_13-8-认为卸载组件会立即卸载共享库" aria-label="Permalink to &quot;13.8 认为卸载组件会立即卸载共享库&quot;">​</a></h3><p>当前 loader 缓存会继续持有库。</p><h3 id="_13-9-混淆-lifecycle-与-component-状态" tabindex="-1">13.9 混淆 Lifecycle 与 Component 状态 <a class="header-anchor" href="#_13-9-混淆-lifecycle-与-component-状态" aria-label="Permalink to &quot;13.9 混淆 Lifecycle 与 Component 状态&quot;">​</a></h3><p>Loaded 只表示对象已经加入 Executor，不表示 Lifecycle Active。</p><h3 id="_13-10-依赖容器全局-remap" tabindex="-1">13.10 依赖容器全局 Remap <a class="header-anchor" href="#_13-10-依赖容器全局-remap" aria-label="Permalink to &quot;13.10 依赖容器全局 Remap&quot;">​</a></h3><p>ComponentManager 默认不把全局参数转发给组件，应显式传递 remapping 和参数，必要时才启用 <code>forward_global_arguments</code>。</p><h2 id="十四、用-nav2-看一个真实组合案例" tabindex="-1">十四、用 Nav2 看一个真实组合案例 <a class="header-anchor" href="#十四、用-nav2-看一个真实组合案例" aria-label="Permalink to &quot;十四、用 Nav2 看一个真实组合案例&quot;">​</a></h2><p>Nav2 中的 PlannerServer、ControllerServer、SmootherServer、BehaviorServer、LifecycleManager 等都通过 <code>RCLCPP_COMPONENTS_REGISTER_NODE</code> 导出。</p><p>当 <code>use_composition=false</code> 时，launch 运行各包自己的可执行文件；当 <code>use_composition=true</code> 时，<code>LoadComposableNodes</code> 把同样的类装入统一容器。节点名、参数、remapping、Lifecycle 接口和业务 Action 都保持不变，变化的是进程与 Executor 布局。</p><p>这正是 Composition 最重要的设计价值：业务架构不需要跟着部署拓扑重写。</p><h2 id="十五、官方依据与本机核验范围" tabindex="-1">十五、官方依据与本机核验范围 <a class="header-anchor" href="#十五、官方依据与本机核验范围" aria-label="Permalink to &quot;十五、官方依据与本机核验范围&quot;">​</a></h2><p>本文交叉核对了以下一手资料：</p><p><a href="https://docs.ros.org/en/humble/Concepts/Intermediate/About-Composition.html" target="_blank" rel="noreferrer">ROS 2 Humble：Composition 概念</a></p><p><a href="https://docs.ros.org/en/humble/How-To-Guides/Launching-composable-nodes.html" target="_blank" rel="noreferrer">ROS 2 Humble：使用 launch 启动 ComposableNode</a></p><p><a href="https://docs.ros.org/en/ros2_packages/humble/api/rclcpp_components/generated/index.html" target="_blank" rel="noreferrer">rclcpp_components Humble API</a></p><p><a href="https://design.ros2.org/articles/intraprocess_communications.html" target="_blank" rel="noreferrer">ROS 2 进程内通信设计文档</a></p><p><a href="https://github.com/ros2/rclcpp/blob/humble/rclcpp_components/src/component_manager.cpp" target="_blank" rel="noreferrer">ros2/rclcpp Humble：ComponentManager 源码</a></p><p><a href="https://github.com/ros2/rclcpp/blob/humble/rclcpp/src/rclcpp/executor.cpp" target="_blank" rel="noreferrer">ros2/rclcpp Humble：Executor 源码</a></p><p>本机核验版本为 <code>rclcpp 16.0.12</code>、<code>rclcpp_components 16.0.12</code>、<code>composition_interfaces 1.2.1</code> 和 <code>launch_ros 0.19.9</code>。不同 ROS 2 发行版可能继续调整接口和 Executor 细节，实际项目应以目标发行版源码为准。</p><h2 id="十六、结语" tabindex="-1">十六、结语 <a class="header-anchor" href="#十六、结语" aria-label="Permalink to &quot;十六、结语&quot;">​</a></h2><p>ROS 2 Composition 并不是简单地“少开几个进程”。它是一条完整的部署机制：构建阶段由 class_loader 和 ament index 建立可发现入口，运行阶段由 ComponentManager 通过 Service 动态构造节点，Executor 汇总全部 CallbackGroup，并沿 <code>rcl_wait()</code>、<code>rmw_wait()</code> 调度回调；需要时，IntraProcessManager 再把消息从 DDS 路径切到进程内缓冲区和 GuardCondition 路径。</p><p>理解这条链路后，才能正确回答三个工程问题：节点为什么加载失败、组件为什么共进程却没有变快，以及一个回调为什么能拖住同容器的整套系统。</p>',218)])])}const f=a(h,[["render",u]]);export{q as __pageData,f as default};
